/* Caring Companions Email Library, generated from Samantha's Claude-design campaign zip (2026-07-20).
   49 emails: monthly prospect calendar (23), client notes (14: holiday and program notes, each written for the client and for the family; the quarterly check-ins were removed 2026-11-14, her word: "same for clients we have check ins elsewhere"), caregiver holiday notes (5; the check-ins, recognition, wellbeing and refer-a-friend emails were removed 2026-11-14, her word: "we are bilding a full system for feedback and check ins elsewhere in the hub"), referral partners (7: the six-email partner series and the note after a referral; the 31 older by-hand emails were retired 2026-11-14, her word: "No old ones by hand"). Kept equal to mo-care.com/email-assets/library.json (website tools/build-email-library.mjs) plus the Hub-only "variant" label.
   ccBuildEmailHTML(e) draws an email with email-template.js; pictures are on mo-care.com/email-assets. */
const CC_EMAIL_LIBRARY = [{"id":1,"month":"January","when":"Early January","cat":"Promo","ac":"#4f8f74","subj":"A gentler kind of New Year's resolution","pre":"This year, you don't have to do it all alone.","eye":"New Year · A Fresh Start","head":"What if this year, you asked for a little help?","hero":"senior and caregiver laughing over morning coffee","blocks":[{"t":"p","text":"Every January brings a flurry of resolutions, eat better, move more, worry less. But if you've been quietly carrying the weight of caring for an aging parent or spouse, here's one worth adding to the list: let someone help."},{"t":"p","text":"At Caring Companions, “help” doesn't mean handing over control. It means a trusted caregiver who folds the laundry, drives to appointments, and shares a cup of coffee, so you can go back to being a daughter, a son, or a spouse instead of the on-call everything."},{"t":"tip","text":"No long-term contract. No rigid packages. Just the hours and support that fit your family, adjusted any time life changes."},{"t":"p","text":"We've walked alongside more than 400 Southwest Missouri families since 2017. We'd be honored to walk alongside yours."}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Warmly,","key":"m1","banner":"h1","seg":"Promo","aud":"monthly","footer":""},{"id":2,"month":"January","when":"Late January","cat":"Educational","ac":"#5d7896","subj":"The quiet danger of a long Missouri winter","pre":"Loneliness can be as hard on health as a chronic illness.","eye":"Caregiving Insights","head":"When the days get short, watch for the quiet signs","hero":"older adult by a frosted winter window, warm interior","blocks":[{"t":"p","text":"Winter in Southwest Missouri can keep anyone indoors, but for an older adult living alone, weeks of gray skies and icy sidewalks can slide quietly into isolation. And loneliness isn't just sad; research links it to higher risks of depression, cognitive decline, and heart trouble."},{"t":"p","text":"A few things to gently look for in the parent or grandparent you love:"},{"t":"l","items":["Less interest in hobbies, phone calls, or the church they used to enjoy","Skipped meals, or a fridge that stays full","Wearing the same clothes, or letting tidy routines slip","A flatter, quieter mood than usual"]},{"t":"p","text":"Sometimes the fix is simply a familiar face a few times a week, someone to share a meal, a walk, or a memory. That's the heart of what our caregivers do."},{"t":"tip","text":"Can't visit as often as you'd like? A caregiver visit a few times a week can fill the quiet days."}],"cta":{"label":"Learn About Companionship Care","href":"https://mo-care.com/companionship-care","kind":"link"},"sign":"With care,","key":"m2","banner":"h2","seg":"Educational","aud":"monthly","footer":""},{"id":3,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","subj":"Love is showing up, even when you can't","pre":"A little companionship goes a long way this February.","eye":"Valentine's Day","head":"The most loving thing isn't always something you can do yourself","hero":"caregiver and senior playing cards together, laughing","blocks":[{"t":"p","text":"This Valentine's season, love might look less like flowers and more like making sure Mom isn't spending another afternoon alone. If you live across town, or across the country, that can be a hard truth to sit with."},{"t":"p","text":"Companionship care exists for exactly this: a caregiver who genuinely enjoys your loved one's stories, plays the card games they love, and notices when something's off, so the people you love feel seen, even on the days you can't be there."},{"t":"q","text":"Wonderful care. They made my dad very comfortable and dealt with him using compassion and friendship.","by":", Debbie B., Google review"},{"t":"p","text":"Because at Caring Companions, our caregivers don't just provide a service. They extend the warmth of family."}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Happy Valentine's Day,","key":"m3","banner":"h3","seg":"Holiday","aud":"monthly","footer":""},{"id":4,"month":"February","when":"Late February","cat":"Awareness","ac":"#b9694a","subj":"A few small things that protect an aging heart","pre":"February is American Heart Month, here's what helps at home.","eye":"American Heart Month","head":"Heart-healthy living gets harder alone, and easier with a hand","hero":"a healthy home-cooked meal being shared at the table","blocks":[{"t":"p","text":"Eating well, staying active, taking medications on time, the basics of heart health sound simple, until age, mobility, or memory get in the way. American Heart Month is a good moment to check in on the daily habits that keep an older heart strong."},{"t":"l","items":["Home-cooked, lower-sodium meals instead of whatever's easiest","A daily walk, even just around the living room","Medications taken correctly, and on schedule","Fewer stressful errands and more restful days"]},{"t":"p","text":"These are exactly the everyday things our caregivers help with, quietly, consistently, in the background of a normal day."}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"To your family's health,","key":"m4","banner":"h4","seg":"Awareness","aud":"monthly","footer":""},{"id":5,"month":"March","when":"Early March","cat":"Educational","ac":"#5d7896","subj":"Noticed something during your last visit?","pre":"The signs are easy to miss, until you know what to look for.","eye":"Caregiving Insights","head":"Trust that little voice that said, “something’s different”","hero":"adult child visiting an aging parent at home","blocks":[{"t":"p","text":"Often it's a visit that does it, you walk into your parent's home and something feels off. Mail piling up. A dent in the car nobody mentioned. Less food in the fridge than there should be. It's easy to talk yourself out of it. Please don't."},{"t":"p","text":"Common signs it may be time for a little support:"},{"t":"l","items":["Unopened bills, or unusual mistakes with money","New bruises, or unsteadiness on their feet","Forgotten medications or doubled-up doses","Weight loss, or expired food in the pantry","Withdrawing from friends and favorite activities"]},{"t":"p","text":"Noticing early is a gift. It means you can put gentle support in place now, and help your loved one stay safe and independent at home far longer."}],"cta":{"label":"Start With a Free Assessment","href":"https://mo-care.com/explore-care-options","kind":"link"},"sign":"We're here when you're ready,","key":"m5","banner":"h5","seg":"Educational","aud":"monthly","footer":""},{"id":7,"month":"April","when":"Early April","cat":"Awareness","ac":"#4f8f74","subj":"You can't pour from an empty cup","pre":"April is Stress Awareness Month. This one’s for you.","eye":"For Family Caregivers","head":"When was the last time someone took care of you?","hero":"a tired family caregiver taking a quiet, restful moment","blocks":[{"t":"p","text":"If you're the one keeping everything running, the appointments, the meals, the medications, the worry at 2 a.m., this note is for you, not your loved one."},{"t":"p","text":"Caregiver burnout is real, and it creeps in quietly: shorter patience, trouble sleeping, your own health sliding down the list. You are not failing. You are doing the work of several people, and you deserve relief."},{"t":"p","text":"That's what respite care is for. Whether it's a few hours a week or a weekend away, we'll step in so you can rest, recharge, and come back to your loved one as you, not just the caregiver."},{"t":"tip","text":"Asking for help isn't giving up. It's how you keep going."}],"cta":{"label":"Ask About Respite Care","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"Take care of you,","key":"m7","banner":"h7","seg":"Awareness","aud":"monthly","footer":""},{"id":8,"month":"April","when":"Late April","cat":"Educational","ac":"#4f8f74","subj":"Spring cleaning that could prevent a fall","pre":"A few small changes around the house make a big difference.","eye":"Home Safety","head":"This spring, clean for safety as much as for shine","hero":"a bright, tidy, safe living room with clear walkways","blocks":[{"t":"p","text":"Falls are the leading cause of injury for older adults, and most happen right at home, often over things we stop noticing after years in the same house. A little spring attention can prevent a lot of heartache."},{"t":"l","items":["Clear walkways of cords, clutter, and loose rugs","Add grab bars in the bathroom and good lighting in hallways","Keep everyday items within easy reach","Tidy garden paths and steps before mowing season"]},{"t":"p","text":"Our caregivers help with light housekeeping and these everyday safety habits, so home stays the safest place to be."}],"cta":{"label":"Learn About Home Support","href":"https://mo-care.com/services/light-housekeeping","kind":"link"},"sign":"Here's to a safe spring,","key":"m8","banner":"h8","seg":"Educational","aud":"monthly","footer":""},{"id":9,"month":"May","when":"May 4–10","cat":"Holiday","ac":"#b9694a","subj":"For every mom who took care of us first","pre":"This Mother’s Day, give her the gift of being cared for.","eye":"Mother's Day","head":"She spent a lifetime caring for everyone else","hero":"a mother and her adult daughter embracing warmly","blocks":[{"t":"p","text":"This Mother's Day, the flowers will be lovely, but the gift she may need most is the one that lasts past the weekend: knowing she's looked after, every day, by someone who treats her like their own."},{"t":"p","text":"For the mom or grandmother who raised you, a caregiver can mean warm meals, a clean home, rides to see friends, and company that brightens an ordinary Tuesday. Dignity, comfort, and a little joy, that's the gift."},{"t":"q","text":"Excellent coordination and fulfillment of care for Mom. Very happy and satisfied with Caring Companions!","by":", Robert G., Google review"},{"t":"p","text":"Happy Mother's Day from all of us at Caring Companions."}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"With gratitude,","key":"m9","banner":"h9","seg":"Holiday","aud":"monthly","footer":""},{"id":10,"month":"May","when":"Late May","cat":"Awareness","ac":"#c79a3a","subj":"Aging at home, on her own terms","pre":"May is Older Americans Month, here’s to independence.","eye":"Older Americans Month","head":"Independence doesn't have to mean doing it all alone","hero":"an active senior gardening contentedly at home","blocks":[{"t":"p","text":"This May, Older Americans Month celebrates a truth the years don't erase: older adults want to live on their own terms, in their own homes, surrounded by their own memories. Nearly everyone we serve says the same thing, “I just want to stay home.”"},{"t":"p","text":"The right support makes that possible. Not by taking over, but by quietly filling the gaps, the heavy chores, the long drives, the tasks that have gotten harder, so the things that matter stay in your loved one's hands."},{"t":"tip","text":"Care that grows with you: from a few visits a week to around-the-clock support, your plan changes as needs change."}],"cta":{"label":"Explore Care Options","href":"https://mo-care.com/explore-care-options","kind":"link"},"sign":"Celebrating you,","key":"m10","banner":"h10","seg":"Awareness","aud":"monthly","footer":""},{"id":11,"month":"June","when":"June 8–14","cat":"Holiday","ac":"#5d7896","subj":"The strong ones need a hand too","pre":"This Father’s Day, make sure Dad is truly okay.","eye":"Father's Day","head":"Dad spent his life being the strong one","hero":"a father and adult son watching a ballgame together","blocks":[{"t":"p","text":"Fathers are famously bad at asking for help. He'll tell you he's “fine,” wave off the cane, and insist he doesn't need anyone fussing over him. And maybe that independence is exactly why you worry."},{"t":"p","text":"A good caregiver knows how to help a proud man keep his dignity, a hand that looks like friendship, not fussing. Someone to share a ballgame with, keep the house in order, and quietly make sure he's safe."},{"t":"p","text":"This Father's Day, let him stay the strong, independent man he's always been, with just a little backup."}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Happy Father's Day,","key":"m11","banner":"h11","seg":"Holiday","aud":"monthly","footer":""},{"id":12,"month":"June","when":"Mid–Late June","cat":"Awareness","ac":"#6f6196","subj":"Caring for someone whose memory is changing","pre":"June is Alzheimer’s & Brain Awareness Month.","eye":"Alzheimer's & Brain Awareness Month","head":"Memory care, with patience built in","hero":"a caregiver gently holding hands with a senior","blocks":[{"t":"p","text":"When a parent or spouse begins to forget, names, routines, sometimes you, it can be one of the loneliest experiences a family faces. This Alzheimer's & Brain Awareness Month is a reminder that you don't have to navigate it by yourself."},{"t":"p","text":"When your loved one lives with dementia, we offer their caregiver added training for those needs: gentle redirection, steady routines, and the patience to meet your loved one wherever they are today. We care for the whole person, not the diagnosis."},{"t":"l","items":["Safe, familiar daily routines","Calm support through confusion or agitation","Engaging activities that spark connection","Respite so family caregivers can breathe"]},{"t":"p","text":"Wherever you are on this road, we'll walk it with you."}],"cta":{"label":"Learn About Dementia & Memory Care","href":"https://mo-care.com/care-paths/dementia","kind":"link"},"sign":"With patience and heart,","key":"m12","banner":"h12","seg":"Awareness","aud":"monthly","footer":""},{"id":13,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","subj":"Independence is worth protecting, at every age","pre":"Happy 4th from Caring Companions.","eye":"Independence Day","head":"This week, we celebrate independence, including theirs","hero":"a multi-generational family gathered on a summer porch","blocks":[{"t":"p","text":"There's something fitting about July. As the fireworks celebrate our country's independence, it's a good moment to think about the independence of the people who raised us, and how to help them keep it."},{"t":"p","text":"For an older adult, independence isn't about doing everything alone. It's about staying in the home they love, keeping their routines, and making their own choices, with just enough support to make it safe."},{"t":"p","text":"That's the whole reason we do this work. Happy Independence Day, from our family to yours."}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Happy 4th of July,","key":"m13","banner":"h13","seg":"Holiday","aud":"monthly","footer":""},{"id":14,"month":"July","when":"Mid July","cat":"Educational","ac":"#c79a3a","subj":"Missouri summers are hard on older bodies","pre":"Heat affects seniors faster, here’s how to help.","eye":"Home Safety","head":"When the heat index climbs, older adults are most at risk","hero":"a senior staying cool indoors with a glass of water","blocks":[{"t":"p","text":"A Southwest Missouri July can be brutal, and aging bodies handle heat far less efficiently than younger ones. Many older adults don't feel thirsty until they're already dehydrated, and some keep the AC off out of habit or worry about the bill."},{"t":"l","items":["Encourage water throughout the day, not just at meals","Keep the home cool, and check that the AC actually works","Plan errands for the cooler morning hours","Watch for dizziness, confusion, or flushed, dry skin"]},{"t":"p","text":"Our caregivers keep an eye on all of it, hydration, comfort, and the warning signs, so a hot day stays just a hot day."}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Stay cool out there,","key":"m14","banner":"h14","seg":"Educational","aud":"monthly","footer":""},{"id":15,"month":"August","when":"Early August","cat":"Service","ac":"#4f8f74","subj":"Going on vacation? We'll stay with Mom.","pre":"Respite care means everyone gets a break.","eye":"Service Spotlight · Respite Care","head":"You deserve a real vacation, not a worried one","hero":"a relaxed family happily heading off on vacation","blocks":[{"t":"p","text":"Summer trips are wonderful, until you're the one who handles Mom's care and there's no one to cover. Too many families either cancel the trip or spend it on the phone, worrying."},{"t":"p","text":"Respite care is the answer. For a weekend or a couple of weeks, a trusted caregiver steps into your routine, same meals, same medications, same comforts, so your loved one is safe and content while you actually rest."},{"t":"tip","text":"Respite isn't just for vacations. Even a few regular hours each week can protect a family caregiver's health and patience."}],"cta":{"label":"Ask About Respite Care","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"Go enjoy yourself,","key":"m15","banner":"h15","seg":"Service","aud":"monthly","footer":""},{"id":16,"month":"August","when":"Late August","cat":"Testimonial","ac":"#c79a3a","subj":"What families tell us after the first few months","pre":"In their own words.","eye":"From Our Families","head":"Sometimes the right help changes everything","hero":"a multi-generational family together and at ease at home","blocks":[{"t":"p","text":"When families first call us, they're usually exhausted, a little guilty, and unsure if they're “ready.” We hear the same thing again and again a few months later: we wish we'd called sooner."},{"t":"q","text":"Have been very impressed with the compassionate care my parents have received in their home. The administration has also been very flexible to work with us and very responsive.","by":", Judy B., Google review"},{"t":"p","text":"Since 2017, more than 400 Southwest Missouri families have trusted us with the people they love most. We'd be honored to earn that trust with yours."}],"cta":{"label":"Talk With a Care Coordinator","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Thank you for trusting us,","key":"m16","banner":"h16","seg":"Testimonial","aud":"monthly","footer":""},{"id":17,"month":"September","when":"Early September","cat":"Awareness","ac":"#4f8f74","subj":"Most falls are preventable. Really.","pre":"September is Healthy Aging Month.","eye":"Healthy Aging Month","head":"A fall can change everything, so let's prevent it","hero":"a senior walking confidently with a caregiver’s support","blocks":[{"t":"p","text":"September's Healthy Aging Month carries one message worth repeating: a single fall can undo years of independence in an instant. The good news is that most falls are preventable with a few steady habits and small changes at home."},{"t":"l","items":["Stay active, gentle movement keeps balance and strength","Review medications that can cause dizziness","Wear supportive, non-slip footwear (no loose slippers!)","Light the path from bed to bathroom for nighttime trips"]},{"t":"p","text":"Our caregivers help with all of it, steady support while walking, safer routines, and a watchful eye that catches hazards before they cause harm."}],"cta":{"label":"Learn About Mobility Support","href":"https://mo-care.com/services/mobility-assistance","kind":"link"},"sign":"To healthy, steady days,","key":"m17","banner":"h17","seg":"Awareness","aud":"monthly","footer":""},{"id":18,"month":"September","when":"Late September","cat":"Service","ac":"#5d7896","subj":"The secret to great care? The right match.","pre":"How we pair your loved one with the right caregiver.","eye":"Service Spotlight · Caregiver Matching","head":"Anyone can send a caregiver. We send the right one.","hero":"a caregiver and senior who clearly enjoy each other","blocks":[{"t":"p","text":"The difference between care that works and care that doesn't usually comes down to one thing: the person who walks through the door. A great match feels less like hiring help and more like welcoming a friend."},{"t":"p","text":"That's why we don't just fill a shift. Our five-step matching process considers personality, interests, skills, and lifestyle, so your loved one and their caregiver actually click."},{"t":"l","items":["A thoughtful assessment of needs and preferences","Matching on compatibility, not just availability","A flexible start, with room to adjust","Ongoing check-ins to keep it working"]},{"t":"p","text":"And if it's ever not the right fit? We'll make it right."}],"cta":{"label":"Take Our Care Questionnaire","href":"https://mo-care.com/assessment","kind":"link"},"sign":"Let's find your perfect match,","key":"m18","banner":"h18","seg":"Service","aud":"monthly","footer":""},{"id":19,"month":"October","when":"Early–Mid October","cat":"Holiday","ac":"#b9694a","subj":"As it cools down, a gentle reminder","pre":"Cozy season is a good time to check in on the ones we love.","eye":"Autumn","head":"The season of slowing down, and looking a little closer","hero":"a cozy autumn scene in a senior’s warm living room","blocks":[{"t":"p","text":"There's a coziness to fall in the Ozarks, sweaters, soups, early evenings. It's also the season when families start gathering again, and when you may notice that the parent you visited last spring seems a little frailer, a little more forgetful, a little more alone."},{"t":"p","text":"If something tugs at you this autumn, trust it. A short conversation now can mean a warm, safe winter for someone you love, and real peace of mind for you."},{"t":"tip","text":"Earlier nights mean more hours alone. A few caregiver visits a week can fill them with warmth and company."}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Cozy wishes,","key":"m19","banner":"h19","seg":"Holiday","aud":"monthly","footer":""},{"id":20,"month":"October","when":"Late October","cat":"Educational","ac":"#5d7896","subj":"Get the house ready before the first freeze","pre":"A little prep now prevents big problems later.","eye":"Home Safety","head":"Before winter sets in, a few things worth checking","hero":"a warm, well-prepared home interior heading into winter","blocks":[{"t":"p","text":"Winter is hard on an older adult's home, and the tasks that keep it safe, clearing gutters, checking the furnace, salting the steps, get harder to do alone every year. A little preparation now prevents cold, costly, and dangerous surprises later."},{"t":"l","items":["Test the heating system and replace furnace filters","Check smoke and carbon-monoxide detectors","Stock up on essentials before icy weather hits","Have a plan for snow, ice, and slick steps"]},{"t":"p","text":"Our caregivers help keep daily life running through the hardest months, errands, meals, warm company, and a safe path to the door."}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Stay warm,","key":"m20","banner":"h20","seg":"Educational","aud":"monthly","footer":""},{"id":21,"month":"November","when":"Nov 10–18","cat":"Awareness","ac":"#b9694a","subj":"This month, we see you","pre":"November is National Family Caregivers Month.","eye":"National Family Caregivers Month","head":"To the family caregivers: thank you, and please rest","hero":"a thanksgiving table surrounded by family","blocks":[{"t":"p","text":"November is National Family Caregivers Month, and Thanksgiving sits right in the middle of it, which feels exactly right. So before the table is set, we want to say it plainly: the quiet, daily work you do for someone you love does not go unseen."},{"t":"p","text":"It's also the season when the work doubles, hosting, traveling, cooking, on top of everything you already carry. Please don't try to do all of it alone. Letting a caregiver cover a few hours isn't stepping back; it's how you make it to the holiday with something left to give."},{"t":"tip","text":"Hosting this year? Respite care can cover the cooking and care so you can simply enjoy your family."},{"t":"p","text":"From our family to yours, thank you, and happy Thanksgiving."}],"cta":{"label":"Ask About Holiday Respite","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"With deep gratitude,","key":"m21","banner":"h21","seg":"Awareness","aud":"monthly","footer":""},{"id":22,"month":"November","when":"Around Nov 11","cat":"Holiday","ac":"#5d7896","subj":"Honoring those who served, at home","pre":"VA-funded home care for the veterans we owe so much.","eye":"Veterans Day","head":"They served our country. Now it's our turn to serve them.","hero":"a veteran and a respectful caregiver in conversation","blocks":[{"t":"p","text":"This Veterans Day, we're thinking of the men and women who gave so much, and of the families now caring for them. What many don't realize is that the care a veteran needs at home may be available at little or no cost through VA programs."},{"t":"p","text":"Caring Companions works with VA Community Care and veteran in-home care programs to bring trained, compassionate caregivers to those who served, with help navigating the benefits along the way."},{"t":"l","items":["VA Community Care and veteran in-home care programs","Help understanding what your loved one qualifies for","Caregivers who honor their service and their dignity"]},{"t":"p","text":"To every veteran in our community: thank you. It would be our privilege to care for you."}],"cta":{"label":"Learn About VA-Funded Care","href":"https://mo-care.com/free-care-for-veterans","kind":"link"},"sign":"With respect and gratitude,","key":"m22","banner":"h22","seg":"Holiday","aud":"monthly","footer":""},{"id":23,"month":"December","when":"Dec 15–22","cat":"Holiday","ac":"#4f8f74","subj":"Home for the holidays? Keep your eyes open.","pre":"Holiday visits often reveal what phone calls hide.","eye":"The Holidays","head":"The holidays bring us home, and show us what's really going on","hero":"a family gathered warmly around a Christmas living room","blocks":[{"t":"p","text":"For many families, the holidays are the one time everyone's under the same roof again. And every year, it's during these visits that adult children realize Mom or Dad needs more help than the weekly phone calls let on."},{"t":"p","text":"As you gather this season, notice gently:"},{"t":"l","items":["Is the home as clean and well-stocked as it used to be?","Are they steady on their feet, and keeping up with medications?","Has there been weight loss, or unexplained bruises?","Do they seem more isolated or forgetful than last year?"]},{"t":"p","text":"If you see something that worries you, you don't have to solve it overnight. Start with a conversation, with them, and with us. We'll help you figure out the next gentle step."},{"t":"tip","text":"We care for families right through the holidays. The earlier you call, the better we can plan."}],"cta":{"label":"Talk With Us This Season","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Merry Christmas from our family to yours,","key":"m23","banner":"h23","seg":"Holiday","aud":"monthly","footer":""},{"id":24,"month":"December","when":"Dec 27–31","cat":"Promo","ac":"#c79a3a","subj":"The gift that lasts long after the holidays","pre":"This year, give peace of mind.","eye":"Season's Greetings","head":"The best gift this year isn't under the tree","hero":"a warm winter window glowing with holiday lights","blocks":[{"t":"p","text":"As another year winds down, the gifts that matter most aren't wrapped, they're the comfort of knowing someone you love is safe, cared for, and not alone. That's a gift you can give all year long."},{"t":"p","text":"Whether it's a few companionship hours a week or hands-on daily care, we'll build a plan that fits your family, with no long-term contract and the freedom to change it anytime."},{"t":"p","text":"Thank you for letting us be part of so many Southwest Missouri families this year. Here's to a healthy, warm, and connected new year."}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Warm wishes for the new year,","key":"m24","banner":"h24","seg":"Promo","aud":"monthly","footer":""},{"id":5,"month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes for the team","subj":"Happy New Year to our incredible team","pre":"Here's to you, and the year ahead.","head":"Wishing you a happy and healthy New Year","blocks":[{"t":"p","text":"As a new year begins, we want to say thank you. The compassion you bring into our clients' homes changes lives, and you are what makes Caring Companions what it is."},{"t":"p","text":"Here's to a year of good health, good shifts, and feeling appreciated for the essential work you do."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","key":"g5","seg":"Holiday","aud":"caregivers","footer":""},{"id":6,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine appreciation for caregivers","subj":"You bring so much heart to this work","pre":"A little Valentine's thank-you for our caregivers.","head":"This Valentine's Day, we're celebrating you","blocks":[{"t":"p","text":"Valentine's Day is about heart, and few people give more of theirs than our caregivers. The warmth, patience, and kindness you show our clients is the truest kind of love there is."},{"t":"p","text":"Thank you for the heart you bring to work every day. We're so grateful for you."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With appreciation,","key":"g6","seg":"Holiday","aud":"caregivers","footer":""},{"id":7,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day thank-you","subj":"Happy 4th of July, and thank you","pre":"A holiday thank-you to those caring for others.","head":"Wishing you a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July! Whether you're off enjoying the holiday or working to keep our clients safe and cared for, we're thinking of you and grateful for you."},{"t":"tip","text":"Covering a holiday shift? Thank you, truly. Reach out to the office anytime if you need anything while you're on."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With thanks,","key":"g7","seg":"Holiday","aud":"caregivers","footer":""},{"id":8,"month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude for caregivers","subj":"This Thanksgiving, we're thankful for you","pre":"Our caregivers are at the top of our gratitude list.","head":"Grateful for you this Thanksgiving","blocks":[{"t":"p","text":"When we count our blessings this Thanksgiving, our caregivers are right at the top of the list. The comfort and dignity you bring to our clients is a gift to entire families."},{"t":"p","text":"Thank you for all you do, especially in a season when your care means even more. Happy Thanksgiving."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With a grateful heart,","key":"g8","seg":"Holiday","aud":"caregivers","footer":""},{"id":9,"month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth for the team","subj":"Happy holidays to our caregiving family","pre":"Warm wishes, and thanks for the shifts that matter most.","head":"Wishing you a warm and joyful holiday season","blocks":[{"t":"p","text":"From all of us at Caring Companions, happy holidays! We hope your season is filled with rest, warmth, and the people you love."},{"t":"tip","text":"To everyone covering holiday shifts so our clients aren't alone, thank you. It's one of the most meaningful things anyone can do, and we don't take it for granted."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love and gratitude,","key":"g9","seg":"Holiday","aud":"caregivers","footer":""},{"id":39,"month":"Any Referral Partner","when":"Partner series · 1","cat":"Partner series","ac":"#14606F","eye":"Why families can trust the referral","hero":"","subj":"Home care your families can check before they call","pre":"Our rates, our agreement and our handbook are all public.","head":"Nothing about our care is hidden until the sales visit","blocks":[{"t":"p","text":"When you suggest a home care agency, the family's first questions are about cost and commitment. With Caring Companions they can answer both before they ever call us."},{"t":"stats","items":[{"big":"$30 to $34","small":"an hour, published on our website"},{"big":"4.9 <span style=\"color:#A88400;\">&#9733;</span>","small":"on Google, from families we serve"},{"big":"Since 2017","small":"locally owned, not a franchise"}]},{"t":"l","items":["No deposit and no long-term contract","The <a href=\"https://mo-care.com/assets/docs/caring-companions-client-handbook.pdf\" style=\"color:#14606F;font-weight:700;\">Client Handbook</a> and the <a href=\"https://mo-care.com/assets/docs/caring-companions-client-care-agreement-sample.pdf\" style=\"color:#14606F;font-weight:700;\">agreement our clients sign</a> are on our website to read first","The assessment is free, 60 to 90 minutes at home, and the family keeps everything in writing"]},{"t":"links","head":"See it for yourself","text":"Everything a family will see is open to you too. Read it before you ever mention our name.","items":[{"t":"Sample Client Care Agreement","d":"The agreement our clients sign, with the rate sheet. PDF.","href":"https://mo-care.com/assets/docs/caring-companions-client-care-agreement-sample.pdf"},{"t":"Client Handbook","d":"How care works, billing, and a client's rights and privacy. PDF.","href":"https://mo-care.com/assets/docs/caring-companions-client-handbook.pdf"},{"t":"Our rates","d":"Every rate, the minimums and the Best Price Guarantee.","href":"https://mo-care.com/pricing"},{"t":"A sample caregiver profile","d":"What a family is sent before the first visit.","href":"https://mo-care.com/our-caregivers#meet-your-caregiver"},{"t":"How we decide","d":"How we recommend a level of care, and when we say home care is not the answer.","href":"https://mo-care.com/how-we-decide"},{"t":"Care cost calculator","d":"Home care beside assisted living and nursing home costs.","href":"https://mo-care.com/cost-calculator"}]}],"cta":{"label":"See what families see","href":"https://mo-care.com/before-your-assessment","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":1,"openers":{"Hospice & Palliative":"Your team manages comfort. The hours between your visits are the part we cover.","Home Health":"When your skilled visits end, most patients still need help with the day. That is the part we do.","Skilled Nursing & Rehab":"A discharge home holds when someone is there to help in the first weeks.","Hospitals & Case Mgmt":"When a patient is going home and the family asks who can help, this is what you can tell them about us.","Senior Living":"When a resident needs more one-on-one time than your staffing allows, our caregivers come to them in your community.","Physicians & Clinics":"Some patients are medically stable and still not managing at home. A few hours of help a week changes that.","Elder Law & Financial":"When your clients ask who to trust for care at home, cost and commitment are their first questions."},"aud":"referrers","key":"r39"},{"id":40,"month":"Any Referral Partner","when":"Partner series · 2","cat":"Partner series","ac":"#14606F","eye":"Why families can trust the referral","hero":"","subj":"Your patients see who is coming before the doorbell rings","pre":"A photo, a story and the caregiver's experience, sent ahead.","head":"Never a stranger at the door","blocks":[{"t":"p","text":"The hardest part of accepting help is letting someone new into the house. Many families put care off for that reason alone."},{"t":"p","text":"Before a first visit, we text the client and family a private link to their caregiver's profile: a photo, a little about them, their experience, and why they do this work. Some caregivers add a short hello video. When the doorbell rings, it is a face they already know."},{"t":"video","href":"https://mo-care.com/our-caregivers#meet-your-caregiver","img":"never-a-stranger","alt":"Never a Stranger: a short video about meeting your caregiver before the first visit","title":"Watch: Never a Stranger","caption":"How a family meets their caregiver before the first visit."},{"t":"p","text":"Every caregiver has passed background checks and is trained before working in a client's home."}],"cta":{"label":"See a sample profile","href":"https://mo-care.com/our-caregivers#meet-your-caregiver","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":2,"aud":"referrers","key":"r40"},{"id":41,"month":"Any Referral Partner","when":"Partner series · 3","cat":"Partner series","ac":"#14606F","eye":"Know what you are referring to","hero":"","subj":"What our caregivers do, and what they don't","pre":"Three levels of non-medical care, with clear limits.","head":"You should know exactly what you are referring to","blocks":[{"t":"p","text":"We provide non-medical care at three levels, and we tell families which one fits at the assessment:"},{"t":"l","items":["Wellness Care: company, meals, light housekeeping, errands and medication reminders","Personal Care: all of that, plus hands-on help with bathing, dressing, toileting and transfers","Advanced Care: more experienced caregivers for advanced dementia and complex mobility needs"]},{"t":"p","text":"The same levels are available overnight and around the clock."},{"t":"p","text":"We are just as clear about the limits. Our caregivers remind clients to take medications. They do not fill pill organizers, check blood sugar, give insulin or handle oxygen. In an emergency they call 911, then our office. That clarity is why clinical teams can work alongside us without wondering who is doing what."}],"cta":{"label":"See each level","href":"https://mo-care.com/our-services","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":3,"aud":"referrers","key":"r41"},{"id":42,"month":"Any Referral Partner","when":"Partner series · 4","cat":"Partner series","ac":"#14606F","eye":"Paying for care","hero":"","subj":"\"How will we pay for it?\" We do the work on that question.","pre":"Long-term care insurance, VA, Medicare GUIDE and open private rates.","head":"A referral only helps if the family can afford to act on it","blocks":[{"t":"p","text":"Cost is where most care plans stall. Here is what we take off the family's plate:"},{"t":"l","items":["Long-term care insurance: we review the policy with them, set up the call with the insurer and help with the claim forms. Depending on the policy, we may be able to bill the insurer directly.","Veterans: we work with VA Community Care for eligible veterans.","Dementia: we are an approved Medicare GUIDE respite provider in southwest Missouri. Families who meet Medicare's criteria can receive 20 four-hour respite visits a year, billed to Medicare.","Private pay: $30, $32 or $34 an hour, published, with a Best Price Guarantee for new private-pay clients. Eligibility terms apply.","Families with active Medicaid? Our sister company, Caring Companions Consumer Directed Services, can help: caringcds.com or (417) 218-2888."]}],"cta":{"label":"See ways to pay","href":"https://mo-care.com/pricing","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":4,"aud":"referrers","key":"r42"},{"id":43,"month":"Any Referral Partner","when":"Partner series · 5","cat":"Partner series","ac":"#14606F","eye":"More than a standard care plan","hero":"","subj":"Three situations we have an answer for","pre":"The person who needs very little, the couple, and the one who isn't at home.","head":"Not every referral fits a standard care plan","blocks":[{"t":"p","text":"Some of the people you see don't fit the usual picture of home care. We built for them too."},{"t":"l","items":["The person who says \"I don't need much.\" Early Support Visits are four-hour visits once a month or every other week, in Springfield: a hand around the house and good company. $152 a visit monthly, $140 every other week.","The couple. One caregiver can help both spouses in the same visit, so they stay together at home.","The person who isn't at home. Our caregivers also give one-on-one care in assisted living, nursing homes, rehab and the hospital, alongside the staff."]}],"cta":{"label":"See all services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":5,"aud":"referrers","key":"r43"},{"id":44,"month":"Any Referral Partner","when":"Partner series · 6","cat":"Partner series","ac":"#14606F","eye":"How a referral works","hero":"","subj":"Referring takes two minutes. Here is what happens next.","pre":"One form, one call to the family, one visit at home.","head":"What happens after you send us a name","blocks":[{"t":"ol","items":["You send the referral: our secure online form, a call to (417) 234-8494, or a fax to (417) 719-7870.","A care coordinator from our Springfield office calls the family, usually the same business day.","We visit them at home for a free assessment and write the care plan with them.","Care can sometimes begin the same day or the next day, depending on caregiver availability."]},{"t":"p","text":"You don't need to qualify the family or explain our prices. Send us the name, and we take it from there."}],"cta":{"label":"Refer a patient","href":"https://mo-care.com/refer","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":6,"aud":"referrers","key":"r44"},{"id":45,"month":"Any Referral Partner","when":"After a referral","cat":"Partner series","ac":"#14606F","eye":"Your referral","hero":"","subj":"We have your referral. Here is what happens now.","pre":"A coordinator is calling the family.","head":"Your referral is with a care coordinator","blocks":[{"t":"p","text":"We received your referral, and a care coordinator from our Springfield office is contacting the family."},{"t":"p","text":"From here we offer them a free assessment at home, recommend a level of care, and put everything in writing before they decide anything. If home care with us is not the right answer for them, we will tell them so."},{"t":"p","text":"If you have questions about this family or another one, call our office at (417) 234-8494."}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"From our Springfield office,","seg":"Any Referral Partner","aud":"referrers","key":"r45"},{"id":5,"month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes","subj":"Happy New Year from all of us","pre":"Here's to a year of comfort and good company.","head":"Wishing you a warm and happy New Year","blocks":[{"t":"p","text":"From your whole Caring Companions family, happy New Year! We feel lucky to start another year alongside you, and we're looking forward to all the ordinary, wonderful days ahead."},{"t":"p","text":"Here's to a year filled with comfort, good company, and feeling right at home, because that's exactly what you deserve."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c5a","variant":"To the client","seg":"Holiday","footer":""},{"id":5,"month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes","subj":"Happy New Year, thank you for trusting us","pre":"Grateful to care for your loved one another year.","head":"Wishing your family a happy and healthy New Year","blocks":[{"t":"p","text":"As a new year begins, we want to say thank you. Trusting us with someone you love is no small thing, and we don't take it for granted."},{"t":"p","text":"Here's to a healthy, comfortable year ahead for your loved one, and please remember, as their needs change, we can grow their care right along with them."},{"t":"tip","text":"A new year is a natural time to revisit the care plan. If you'd like to talk through any adjustments, we're just a call away."}],"cta":{"label":"Call Us · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","aud":"client_contacts","key":"c5b","variant":"To the family contact","seg":"Holiday","footer":""},{"id":6,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine warmth","subj":"You're family to us","pre":"A little Valentine's note, just for you.","head":"This Valentine's Day, we're thinking of you","blocks":[{"t":"p","text":"Valentine's Day is about the people who fill our lives with warmth, and you're one of those people for us. It's a joy to spend our days with you."},{"t":"p","text":"Thank you for your stories, your smiles, and for letting us be part of your life. Happy Valentine's Day."}],"cta":{"label":"We're Always Just a Call Away","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c6a","variant":"To the client","seg":"Holiday","footer":""},{"id":6,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine warmth","subj":"Thinking of your loved one this Valentine's Day","pre":"A note of appreciation, and a gentle thought.","head":"Sending a little extra warmth this Valentine's","blocks":[{"t":"p","text":"This Valentine's Day, we're grateful for the chance to care for someone you love. We hope they feel the warmth and companionship of the season."},{"t":"tip","text":"If your loved one ever feels lonely between visits, especially in these quieter winter months, a few extra companionship hours can brighten their days. Just say the word."}],"cta":{"label":"Add a Little Extra Company","href":"tel:4172348494","kind":"call"},"sign":"With warm regards,","aud":"client_contacts","key":"c6b","variant":"To the family contact","seg":"Holiday","footer":""},{"id":7,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day wishes","subj":"Happy 4th of July!","pre":"Warm wishes for a safe, happy holiday.","head":"Wishing you a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July! We hope your day is filled with good food, familiar faces, and a little celebration. However you spend it, know we're thinking of you."},{"t":"p","text":"And as the summer heats up, please remember to stay cool and hydrated, your caregiver is always here to help."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"clients","key":"c7a","variant":"To the client","seg":"Holiday","footer":""},{"id":7,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day wishes","subj":"Happy 4th, and a note on holiday support","pre":"Holiday wishes and support options.","head":"Wishing your family a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July from all of us! We hope your family enjoys a wonderful holiday together."},{"t":"tip","text":"Traveling or hosting this summer? We can add hours, overnight, or respite care so your loved one stays safe and comfortable, and you can relax. Just let us know."},{"t":"p","text":"Our caregivers are also keeping a close eye on summer heat and hydration for your loved one."}],"cta":{"label":"Ask About Extra Summer Support","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"client_contacts","key":"c7b","variant":"To the family contact","seg":"Holiday","footer":""},{"id":8,"month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude","subj":"We're thankful for you","pre":"A Thanksgiving note from your care team.","head":"This Thanksgiving, we're grateful for you","blocks":[{"t":"p","text":"When we count our blessings this Thanksgiving, you're near the top of the list. It's a true gift to spend our days with you, and we're thankful for every moment."},{"t":"p","text":"We hope your holiday is warm, comfortable, and full of the people and things you love."}],"cta":{"label":"We're Always Just a Call Away","href":"tel:4172348494","kind":"call"},"sign":"With a grateful heart,","aud":"clients","key":"c8a","variant":"To the client","seg":"Holiday","footer":""},{"id":8,"month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude","subj":"Grateful to care for your loved one this Thanksgiving","pre":"Thank you, and a little holiday help if you need it.","head":"This Thanksgiving, thank you for trusting us","blocks":[{"t":"p","text":"This season of gratitude, we want you to know how thankful we are for the trust you place in us to care for someone so important to your family."},{"t":"tip","text":"Hosting, traveling, or simply stretched thin this Thanksgiving? Extra caregiver hours or respite can lighten the load so you can be present with your family. We'd be glad to help."}],"cta":{"label":"Add Holiday Support","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","aud":"client_contacts","key":"c8b","variant":"To the family contact","seg":"Holiday","footer":""},{"id":9,"month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth","subj":"Merry Christmas and happy holidays","pre":"Warm wishes for a cozy, joyful season.","head":"Wishing you a warm and joyful holiday season","blocks":[{"t":"p","text":"From all of us at Caring Companions, we're wishing you the merriest, coziest holiday season. May your days be filled with warmth, good memories, and the people who love you."},{"t":"p","text":"And if the season ever feels quiet, remember, you're never alone. We're always just a phone call away."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love and warm wishes,","aud":"clients","key":"c9a","variant":"To the client","seg":"Holiday","footer":""},{"id":9,"month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth","subj":"Warm holiday wishes, and a little extra help if you need it","pre":"Season's greetings and holiday support options.","head":"Happy holidays from your loved one's care team","blocks":[{"t":"p","text":"Wishing your whole family a warm and joyful holiday season. It's been our honor to care for your loved one this year."},{"t":"tip","text":"The holidays can be a lot, hosting, traveling, extra visitors. If you'd like additional hours, overnight care, or respite so everyone can enjoy the season, we care for families right through the holidays. The earlier you let us know, the better we can plan."},{"t":"p","text":"Whatever you need, we're here. Merry Christmas and happy holidays."}],"cta":{"label":"Arrange Extra Holiday Care","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"client_contacts","key":"c9b","variant":"To the family contact","seg":"Holiday","footer":""},{"id":11,"month":"November","when":"Early November","cat":"Program","ac":"#b9694a","banner":"h19","eye":"Holiday Support","hero":"extra holiday support","subj":"Want a little extra company this season?","pre":"More help is here whenever you'd like it.","head":"The holidays are merrier with company","blocks":[{"t":"p","text":"The holidays can be busy and bright, or sometimes just a bit quiet. Whichever they are for you this year, we'd love to make them warmer."},{"t":"p","text":"If you'd enjoy some extra company, a hand with holiday cooking, help getting to gatherings, or just a few more visits, all you have to do is ask. We're here for you."}],"cta":{"label":"Just Say the Word","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c11a","variant":"To the client","seg":"Program","footer":""},{"id":11,"month":"November","when":"Early November","cat":"Program","ac":"#b9694a","banner":"h19","eye":"Holiday Support","hero":"extra holiday support","subj":"Extra support for your loved one this holiday season","pre":"Add hours, overnight, or respite. Let us know early.","head":"A little extra help can make the holidays easier","blocks":[{"t":"p","text":"The holidays often bring more to juggle, travel, hosting, visitors, and a busier schedule for everyone. They can also be a lonelier, more disorienting time for older adults."},{"t":"p","text":"We're here to help however you need. A few options families love this time of year:"},{"t":"l","items":["Extra daytime hours for company and holiday prep","Overnight or 24-hour care while you travel or host","Respite care so the whole family can be present","Transportation to gatherings and appointments"]},{"t":"tip","text":"Caregivers book up quickly around the holidays, the earlier you let us know, the better we can plan."}],"cta":{"label":"Arrange Holiday Support","href":"tel:4172348494","kind":"call"},"sign":"With warm regards,","aud":"client_contacts","key":"c11b","variant":"To the family contact","seg":"Program","footer":""},{"id":12,"month":"Anytime","when":"Send anytime","cat":"Program","ac":"#5d7896","banner":"h5","eye":"Did You Know?","hero":"more ways we can help","subj":"A few more ways we're here for you","pre":"Did you know we can help with all of this?","head":"More ways we can help, whenever you need","blocks":[{"t":"p","text":"You may know us for the help you receive today, but there's a lot more we can do whenever you'd like. We're always ready to do more, never less."},{"t":"l","items":["Rides to appointments, errands, and the store","Help with meals, light housekeeping, and laundry","A nurse visit for medication management","Bathing, dressing, and personal care support"]},{"t":"p","text":"If any of these would make life easier, just mention it to your caregiver or give us a call."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Warmly,","aud":"clients","key":"c12a","variant":"To the client","seg":"Program","footer":""},{"id":12,"month":"Anytime","when":"Send anytime","cat":"Program","ac":"#5d7896","banner":"h5","eye":"Did You Know?","hero":"more ways we can help","subj":"Did you know we offer all of this?","pre":"Care that can grow with your loved one's needs.","head":"More ways we can support your loved one","blocks":[{"t":"p","text":"As your loved one's needs change, their care can change right along with them, no new agency, no starting over. Here are some of the ways we can do more:"},{"t":"l","items":["Private-duty nursing and medication management","Personal care, bathing, dressing, mobility","Respite care to support family caregivers","Help at home after a hospital stay or illness","Care for dementia, Parkinson's, and more","VA, Medicare GUIDE, and long-term care insurance options","Have active Medicaid? Our sister company, Caring Companions Consumer Directed Services, can help: caringcds.com or (417) 218-2888."]},{"t":"tip","text":"Noticing your loved one needs a little more lately? Let's revisit the plan, we'll make it seamless."}],"cta":{"label":"Explore More Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Warmly,","aud":"client_contacts","key":"c12b","variant":"To the family contact","seg":"Program","footer":""}];
const CC_EMAIL_ASSETS = 'https://mo-care.com/email-assets';
const CC_EMAIL_LOGO = CC_EMAIL_ASSETS + '/cc-logo.png';
/* The look lives in email-template.js (2026-11-13), the same file the server's scheduled sender uses, so a preview here
   is what goes out. '{unsub}' is each person's own unsubscribe link, filled in by the server when it sends. */
function ccBuildEmailHTML(e, seg){
  /* seg: the partner type of the organization it is going to, when one partner is being written to (partner-emails.js) */
  return CCEmailTemplate.build(e, { unsub:'{unsub}', assets:CC_EMAIL_ASSETS, seg:seg || '' });
}
